# -*- coding: utf-8 -*-
"""ПУЛ-СВОБОДА (рядок 5510): скільки речей руки 1 знімає кожна смуга добору на типових сценах — каталог → абсолютні
фільтри (`_придатні`) → слот з ошатністю й вікнами палітри (`_кандидати_на_слот`) → відсічення (`відсікти_пул`) →
бюджет символів (семплер); окремо — шлях сукні. Живий міст `запити` на `стенд_вх` + повний каталог; лічба — перший
виклик (рука 1). Запуск із теки `джерела`: python3 проби/пул_свобода_смуги.py  (≈4 хв)"""
import sys, os, json, collections
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(sys.path[0])
import bridge as B, feed as Ф, композитор_збирання as КЗ, pipeline as ПМ
Л = {}
def обгорнути(мод, ім, запис):
    стара = getattr(мод, ім)
    def нова(*a, **k): р = стара(*a, **k); запис(a, р); return р
    setattr(мод, ім, нова)
обгорнути(КЗ, "_придатні", lambda a, р: Л.setdefault("придатні", (len(a[0]), len(р[0]), {x["причина"][:44]: x["скільки"] for x in р[1]})))
обгорнути(КЗ, "_кандидати_на_слот", lambda a, р: Л.setdefault("слоти", {}).setdefault(a[2], (sum(1 for r in a[0] if r.get("слот") == a[2] or a[2] in (r.get("слоти_альт") or ())), {r.get("id") for r in р[0]}, р[2])))
обгорнути(ПМ, "відсікти_пул", lambda a, р: Л.setdefault("відсічено", (sum(map(len, a[0].values())), sum(map(len, р[0].values())), р[1]["лічба"])))
КАТ, База = Ф.каталог_на_диску("каталог_повний.xml"), json.load(open("стенд_вх.json", encoding="utf-8"))
СЦЕНИ = {
    "офіс 09:00 +18 business_casual": (База["сценарій"], dict(ошатність=[5, 6])),
    "побачення ресторан 19:00 дощ smart_casual (тест 14.10)": (dict(нагода="побачення", місце="ресторан_районний", дрес_код="smart_casual", година=19, темп_c=18, опади="дощ", мета="лестити"), dict(ошатність=[4, 6], мета="лестити")),
    "весілля гостею 17:00 +18": (dict(нагода="весілля_гість", місце="весілля_вечірнє", година=17, темп_c=18), dict(ошатність=[6, 8])),
    "кав'ярня 11:00 +26": (dict(нагода="щоденне", місце="кафе", година=11, темп_c=26), dict(ошатність=[2, 4])),
    "місто взимку 12:00 −5 сніг": (dict(нагода="щоденне", місце="місто", година=12, темп_c=-5, опади="сніг"), dict(ошатність=[3, 4])),
    "театр 19:00 +16": (dict(нагода="культура", місце="театр", година=19, темп_c=16), dict(ошатність=[6, 7])),
}
for назва, (сц, пасп) in СЦЕНИ.items():
    Л.clear()
    r = json.loads(B.виклик("запити", json.dumps(dict(База, каталог=КАТ, сценарій=сц, паспорт=dict(пасп, **{к: сц[к] for к in ("темп_c", "місце", "година", "опади", "дрес_код") if к in сц}), випадок=назва), ensure_ascii=False)))
    кат, прид, відк = Л["придатні"]; сл = Л["слоти"]; у_вікнах = set().union(*(s for _, s, _ in сл.values())); до, після, лч = Л["відсічено"]; ст = r["стеля"]
    print("\n%s · смуга %s · намір %s" % (назва, r["мета"].get("формальність"), r["мета"].get("намір")))
    print("  каталог %d → абсолютні %d (%s)" % (кат, прид, ", ".join("%s %d" % кв for кв in відк.items()) or "—"))
    print("  %d слотів: %d місць у слотах (з альт) → після ошатності слота й вікон палітри %d речей" % (len(сл), sum(n for n, _, _ in сл.values()), len(у_вікнах)))
    print("  відсічення: %d → %d місць (%s)" % (до, після, ", ".join("%s %d" % кв for кв in sorted(лч.items(), key=lambda x: -x[1]))))
    print("  бюджет: повний пул %s симв. → пул %s речей, %s симв. (бюджет %s)" % (next((ч["values"].get("full_chars") for ч in ст.get("чому") or [] if ч.get("code") == "pool_cut_to_budget"), "≤бюджету"), r["пул_речей"], ст.get("пул_символів"), ст.get("бюджет")))
    сук = r["кандидати"].get("сукня") or []; нс, іс, лс = сл.get("сукня", (0, set(), None))
    print("  сукня: у слоті %d → після вікон %d (ошатність слота: %s) → у пулі %d; блиск ≥2: %d; сім'ї: %s; «нижче смуги» в пулі всього %d" % (нс, len(іс), лс, len(сук), sum(1 for x in сук if (x.get("блиск") or 0) >= 2), dict(collections.Counter(x.get("сім_я") for x in сук).most_common(4)), sum(1 for в in r["кандидати"].values() for x in в if x.get("_нижче_смуги"))))
